def rule(state: list) -> bool:
    def count_on_objects():
        count = 0
        for obj in state:
            if obj:
                count += 1
        return count

    def sum_of_on_objects():
        total_sum = 0
        for index in range(len(state)):
            if state[index]:
                total_sum += index
        return total_sum

    on_count = count_on_objects()
    on_sum = sum_of_on_objects()

